using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class MargaretAtwood
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "The Eskimo has fifty-two names for snow because it is important to them; there ought to be as many for love.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "A divorce is like an amputation; you survive, but there’s less of you.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "I would rather dance as a ballerina, though faultily, than as a flawless clown.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Another belief of mine: that everyone else my age is an adult, whereas I am merely in disguise.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Time is not a line but a dimension, like the dimensions of space.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "An eye for an eye only leads to more blindness.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "War is what happens when language fails.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "I am certain that a Sewing Machine would relieve as much human suffering as a hundred Lunatic Asylums, and possibly a good deal more.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "I'm working on my own life story. I don't mean I'm putting it together; no, I'm taking it apart.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "I can tell you that once upon a time when I was doing public events people would ask me, \"What do you think about the arts?, What do you think of the role of women?, What do you think of men?, What do you think of all of these things?\", and now they ask one thing, and that one thing is this, \"Is there hope?\"", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "The weapons that were once outside sharpening themselves on war are now indoors there, in the fortress, fragile in glass cases. Why is it that in this time, such elaborate defences keep things that are no longer (much) worth defending?", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Your righteous eyes, your laconic trigger-fingers people the streets with villains: as you move, the air in front of you blossoms with targets and you leave behind you a heroic trail of desolation: beer bottles slaughtered by the side of the road, bird-skulls bleaching in the sunset.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "I am the horizon you ride towards, the thing you can never lasso. I am also what surrounds you: my brain scattered with your tincans, bones, empty shells, the litter of your invasions. I am the space you desecrate as you pass through.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "When you hear me singing you get the rifle down and the flashlight, aiming for my brain, but you always miss and when you set out the poison I piss on it to warn the others.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "I am yours. If you feed me garbage, I will sing a song of garbage. This is a hymn.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "In view of the fading animals the proliferation of sewers and fears the sea clogging, the air nearing extinction we should be kind, we should take warning, we should forgive each other Instead we are opposite, we touch as though attacking, the gifts we bring even in good faith maybe warp in our hands to implements, to manoeuvres", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "In restaurants we argue over which of us will pay for your funeral though the real question is whether or not I will make you immortal.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "There is more than one kind of freedom, said Aunt Lydia. Freedom to and freedom from. In the days of anarchy, it was freedom to. Now you are being given freedom from. Don't underrate it.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Tell, rather than write, because I have nothing to write with and writing is in any case forbidden. But if it’s a story, even in my head, I must be telling it to someone. You don’t tell a story only to yourself. There’s always someone else. Even when there is no one.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Ignoring isn’t the same as ignorance, you have to work at it.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "You must cultivate poverty of spirit. Blessed are the meek. She didn’t go on to say anything about inheriting the earth.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "The sitting room is subdued, symmetrical; it’s one of the shapes money takes when it freezes.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Blessed are they that mourn, for they shall be comforted. Nobody said when.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Sanity is a valuable possession; I hoard it the way people once hoarded money. I save it, so I will have enough, when the time comes.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "A man is just a woman’s strategy for making other women.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "You can think clearly only with your clothes on.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "He was not a monster, to her. Probably he had some endearing trait: he whistled, off key, in the shower, he had a yen for truffles, he called his dog Liebchen and made it sit up for little pieces of raw steak. How easy it is to invent a humanity, for anyone at all.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "I'll take care of it, Luke said. And because he said it instead of her, I knew he meant kill. That is what you have to do before you kill, I thought. You have to create an it, where none was before. You do that first, in your head, and then you make it real.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Now we come to forgiveness. Don’t worry about forgiving me right now. There are more important things. For instance: keep the others safe, if they are safe. Don’t let them suffer too much. If they have to die, let it be fast. You might even provide a Heaven for them. We need You for that. Hell we can make for ourselves.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "You can’t make an omelette without breaking eggs, is what he says. We thought we could do better. Better? I say, in a small voice. How can he think this is better? Better never means better for everyone, he says. It always means worse, for some.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Freedom, like everything else, is relative.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "A movie about the past is not the same as the past.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "By telling you anything at all I'm at least believing in you, I believe you're there, I believe you into being. Because I'm telling you this story I will your existence. I tell, therefore you are.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "As all historians know, the past is a great darkness, and filled with echoes. Voices may reach us from it; but what they say to us is imbued with the obscurity of the matrix out of which they come; and, try as we may, we cannot always decipher them precisely in the clearer light of our own day.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "She has been condemned to death by hanging. A man may escape this death by becoming the hangman, a woman by marrying the hangman. But at the present time there is no hangman; thus there is no escape. There is only a death, indefinitely postponed. This is not fantasy, it is history.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "To live in prison is to live without mirrors. To live without mirrors is to live without the self.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "You wonder about her crime. She was condemned to death for stealing clothes from her employer, from the wife of her employer. She wished to make herself more beautiful. This desire in servants was not legal.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "My friends, who are both women, tell me their stories, which cannot be believed and which are true. They are horror stories and they have not happened to me, they have not yet happened to me, they have happened to me but we are detached, we watch our unbelief with horror.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "The fact is there are no stories I can tell my friends that will make them feel better. History cannot be erased, although we can soothe ourselves by speculating about it.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "There is so much silence between the words, you say. You say, The sensed absence of God and the sensed presence amount to much the same thing, only in reverse. You say, I have too much white clothing. You start to hum. Several hundred years ago this could have been mysticism or heresy. It isn’t now. Outside there are sirens. Someone’s been run over. The century grinds on.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Confess: it’s my profession that alarms you. This is why few people ask me to dinner, though Lord knows I don’t go out of my way to be scary.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "My trade is courage and atrocities. I look at them and do not condemn. I write things down the way they happened, as near as can be remembered. I don’t ask why, because it is mostly the same. Wars happen because the ones who start them think they can win.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Despite the propaganda, there are no monsters, or none that can be finally buried. Finish one off, and circumstances and the radio create another. Believe me: whole armies have prayed fervently to God all night and meant it, and been slaughtered anyway. Brutality wins frequently, and large outcomes have turned on the invention of a mechanical device, viz. radar. True, valour sometimes counts for something, as at Thermopylae. Sometimes being right — though ultimate virtue, by agreed tradition, is decided by the winner. Sometimes men throw themselves on grenades and burst like paper bags of guts to save their comrades. I can admire that. But rats and cholera have won many wars. Those, and potatoes, or the absence of them.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "It's a feature of our age that if you write a work of fiction, everyone assumes that the people and events in it are disguised biography — but if you write your biography, it's equally assumed you're lying your head off. This last may be true, at any rate of poets: Plato said that poets should be excluded from the ideal republic because they are such liars. I am a poet, and I affirm that this is true. About no subject are poets tempted to lie so much as about their own lives; I know one of them who has floated at least five versions of his autobiography, none of them true. I of course — being also a novelist — am a much more truthful person than that. But since poets lie, how can you believe me?", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "I became a poet at the age of sixteen. I did not intend to do it. It was not my fault.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "When I was sixteen, it was simple. Poetry existed; therefore it could be written; and nobody had told me — yet — the many, many reasons why it could not be written by me.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "A lot of being a poet consists of willed ignorance. If you woke up from your trance and realized the nature of the life-threatening and dignity-destroying precipice you were walking along, you would switch into actuarial sciences immediately. If I had not been ignorant in this particular way, I would not have announced to an assortment of my high school female friends, in the cafeteria one brown-bag lunchtime, that I was going to be a writer. I said \"writer,\" not \"poet;\" I did have some common sense. But my announcement was certainly a conversation-stopper. Sticks of celery were suspended in mid-crunch, peanut-butter sandwiches paused halfway between table and mouth; nobody said a word. One of those present reminded me of this incident recently — I had repressed it — and said she had been simply astounded. \"Why?,\" I said. \"Because I wanted to be a writer?\" \"No,\" she said. \"Because you had the guts to say it out loud.\"", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "After a year or two of keeping my head down and trying to pass myself off as a normal person, I made contact with the five other people at my university who were interested in writing; and through them, and some of my teachers, I discovered that there was a whole subterranean Wonderland of Canadian writing that was going on just out of general earshot and sight", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "I no longer feel I'll be dead by thirty; now it's sixty. I suppose these deadlines we set for ourselves are really a way of saying we appreciate time, and want to use all of it. I'm still writing, I'm still writing poetry, I still can't explain why, and I'm still running out of time.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Her mother volunteered that the thing about people from another culture was that you could never tell whether they were insane or not because their ways were so different.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "For every age there is a popular idea about what madness is, what causes it, and how a mad person should look and behave; and it's usually these popular ideas, rather than those of medical professionals, that turn up in songs and stories and plays and books.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "When women let their hair down, it means either sexiness or craziness or death, the three by Victorian times having become virtually synonymous.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "As I was writing about Grace Marks, and about her interlude in the Asylum, I came to see her in context — the context of other people's opinions, both the popular images of madness and the scientific explanations for it available at the time. A lot of what was believed and said on the subject appears like sheer lunacy to us now. But we shouldn't be too arrogant — how many of our own theories will look silly when those who follow us have come up with something better? But whatever the scientists may come up with, writers and artists will continue to portray altered mental states, simply because few aspects of our nature fascinate people so much. The so-called mad person will always represent a possible future for every member of the audience — who knows when such a malady may strike? When \"mad,\" at least in literature, you aren't yourself; you take on another self, a self that is either not you at all, or a truer, more elemental one than the person you're used to seeing in the mirror. You're in danger of becoming, in Shakespeare's works, a mere picture or beast, and in Susanna Moodie's words, a mere machine; or else you may become an inspired prophet, a truth-sayer, a shaman, one who oversteps the boundaries of the ordinarily visible and audible, and also, and especially, the ordinarily sayable. Portraying this process is deep power for the artist, partly because it's a little too close to the process of artistic creation itself, and partly because the prospect of losing our self and being taken over by another, unfamiliar self is one of our deepest human fears.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "All stories are about wolves. All worth repeating, that is. Anything else is sentimental drivel. Think about it. There's escaping from the wolves, fighting the wolves, capturing the wolves, taming the wolves. Being thrown to the wolves, or throwing others to the wolves so the wolves will eat them instead of you. Running with the wolf pack. Turning into a wolf. Best of all, turning into the head wolf. No other decent stories exist.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "The only way you can write the truth is to assume that what you set down will never be read. Not by any person, and not even by yourself at some later date. Otherwise you begin excusing yourself. You must see the writing as emerging like a long scroll of ink from the index finger of your right hand; you must see your left hand erasing it.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Nature is to zoos as God is to churches.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "He doesn't know which is worse, a past he can't regain or a present that will destroy him if he looks at it too clearly. Then there's the future. Sheer vertigo.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "After everything that's happened, how can the world still be so beautiful? Because it is.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "All it takes, said Crake, is the elimination of one generation. One generation of anything. Beetles, trees, microbes, scientists, speakers of French, whatever. Break the link in time between one generation and the next, and it’s game over forever.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "When any civilization is dust and ashes, he said, art is all that's left over. Images, words, music. Imaginative structures. Meaning—human meaning, that is—is defined by them. You have to admit that.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "There's something to be said for hunger: at least it lets you know you're still alive.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "He has to find more and better ways of occupying his time. His time, what a bankrupt idea, as if he's been given a box of time belonging to him alone, stuffed to the brim with hours and minutes that he can spend like money. Trouble is, the box has holes in it and the time is running out, no matter what he does with it.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "I am not my childhood, Snowman says out loud.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Anyway, maybe there weren't any solutions. Human society, corpses and rubble. It never learned, it made the same cretinous mistakes over and over, trading short-term gain for long-term pain.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Everybody knew. Nobody admitted to knowing. If other people began to discuss it, you tuned them out, because what they were saying was both so obvious and so unthinkable. We are using up the Earth. It is almost gone.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "What am I living for and what am I dying for are the same question.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "You can forget who you are if you're alone too much.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "we must be a beacon of hope, because if you tell people there's nothing they can do, they will do worse than nothing.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "I could see how you could do extreme things for the person you loved. Adam One said that when you loved a person, that love might not always get returned the way you wanted, but it was a good thing anyway because love went out all around you like an energy wave, and a creature you didn't know would be helped by it.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "How easy it is, treachery. You just slide into it.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "We shouldn't have been so scornful; we should have had compassion. But compassion takes work, and we were young.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Without the light, no chance; without the dark, no dance.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "As with all knowledge, once you knew it, you couldn't imagine how it was that you hadn't known it before. Like stage magic, knowledge before you knew it took place before your very eyes, but you were looking elsewhere.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "I'm fine, said Pilar, for the moment. And the moment is the only time we can be fine in.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "You couldn’t leave words lying around where our enemies might find them.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "It's better to hope than mope!", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "time is not a thing that passes, said Pilar: it’s a sea on which you float.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "There were a lot of utopias in the nineteenth century, wonderful societies that we might possibly construct. Those went pretty much out of fashion after World War I. And almost immediately one of the utopias that people were trying to construct, namely the Soviet Union, threw out a writer called Zamyatin who wrote a seminal book called We, which contains the seeds of Orwell and Huxley. Writers started doing dystopias after we saw the effects of trying to build utopias that required, unfortunately, the elimination of a lot of people before you could get to the perfect point, which never arrived. I don’t believe in a perfect world. I don’t believe it’s achievable, and I believe the people who try to achieve it usually end up turning it into something like Cambodia or something very similar because purity tests set in. Are you ideologically pure enough to be allowed to live? Well, it turns out that very few people are, so you end up with a big powerful struggle and a mass killing scene.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "The fabric of democracy is always fragile everywhere because it depends on the will of citizens to protect it, and when they become scared, when it becomes dangerous for them to defend it, it can go very quickly.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "A lot of people facing fascism didn’t become fascists. I don’t happen to believe that we are all monsters.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "There's the story, then there's the real story, then there's the story of how the story came to be told. Then there's what you leave out of the story. Which is part of the story too.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Life is warped. I'm just in sync.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "But hatred and viciousness are addictive. You can get high on them. Once you've had a little, you start shaking if you don't get more.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Why is it always such a surprise? thinks Toby. The moon. Even though we know it's coming. Every time we see it, it makes us pause, and hush.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "People need such stories, because however dark, a darkness with voices in it is better than a silent void.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Why is war so much like a practical joke? she thinks. Hiding behind bushes, leaping out, with not much difference between Boo! and Bang! except the blood.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Amazing how quickly the past becomes idyllic.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Gender roles suck, says Swift Fox. Then you should stop playing them, thinks Toby.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "My fundamental position is that women are human beings, with the full range of saintly and demonic behaviours this entails, including criminal ones. They're not angels, incapable of wrongdoing. If they were, we wouldn't need a legal system.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Nor do I believe that women are children, incapable of agency or of making moral decisions. If they were, we're back to the 19th century, and women should not own property, have credit cards, have access to higher education, control their own reproduction or vote. There are powerful groups in North America pushing this agenda, but they are not usually considered feminists.", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Furthermore, I believe that in order to have civil and human rights for women there have to be civil and human rights, period …", Author = "Margaret Atwood" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Atwood", Text = "Anyone who doesn't puppet their views is seen as an apostate, a heretic or a traitor, and moderates in the middle are annihilated. Fiction writers are particularly suspect because they write about human beings, and people are morally ambiguous.", Author = "Margaret Atwood" },
        };
    }
}